      out.write("<!---------------------------------- 채팅방 목록 불러오기 --------------------------------->\r\n");
      out.write("<script>\r\n");
      out.write("\r\n");
      out.write("  // 채팅방 선택 css 를 위한 전역변수\r\n");
      out.write("  let selectedRoom = null;\r\n");
      out.write("\r\n");
      out.write("    // 화면 로딩 된 후\r\n");
      out.write("    $(window).on('load', function(){\r\n");
      out.write("\r\n");
      out.write("      getRoomList();\r\n");
      out.write("          \r\n");
      out.write("      // 2초에 한번씩 채팅 목록 불러오기(실시간 알림 전용)\r\n");
      out.write("      setInterval(function(){\r\n");
      out.write("        // 방 목록 불러오기\r\n");
      out.write("        getRoomList();\r\n");
      out.write("        \r\n");
      out.write("        /*\r\n");
      out.write("        // 읽지 않은 메세지 총 갯수가 0개가 아니면\r\n");
      out.write("        if(countAll != 0){\r\n");
      out.write("          // 채팅 icon 깜빡거리기\r\n");
      out.write("          $('.chatIcon').addClass('iconBlink');\r\n");
      out.write("          play();\r\n");
      out.write("        }else{\r\n");
      out.write("          // 깜빡거림 없애기\r\n");
      out.write("          $('.chatIcon').removeClass('iconBlink');\r\n");
      out.write("        }\r\n");
      out.write("        */\r\n");
      out.write("      },2000);\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("  // 채팅 방 목록 가져오기\r\n");
      out.write("  function getRoomList() {\r\n");
      out.write("\r\n");
      out.write("    $.ajax({\r\n");
      out.write("      url:\"chatRoomList.do\",\r\n");
      out.write("      data:{\r\n");
      out.write("          userNo:\"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${loginUser.userNo}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("\"\r\n");
      out.write("      },\r\n");
      out.write("      dataType:\"json\",\r\n");
      out.write("      async:false, // async : false를 줌으로써 비동기를 동기로 처리 할 수 있다.\r\n");
      out.write("      success:function(data){\r\n");
      out.write("\r\n");
      out.write("        // 현재 로그인 된 User들\r\n");
      out.write("        let loginList = \"\";\r\n");
      out.write("          \r\n");
      out.write("        // 로그인 된 User들을 가져온다.\r\n");
      out.write("        $.ajax({\r\n");
      out.write("          url:\"chatSession.do\",\r\n");
      out.write("          data:{\r\n");
      out.write("          },\r\n");
      out.write("          async:false,\r\n");
      out.write("          dataType:\"json\",\r\n");
      out.write("          success:function(data){\r\n");
      out.write("            for(var i = 0; i < data.length; i++){\r\n");
      out.write("                loginList += data[i];\r\n");
      out.write("            }\r\n");
      out.write("          }\r\n");
      out.write("        });\r\n");
      out.write("          \r\n");
      out.write("        $chatWrap = $(\".chatList\");\r\n");
      out.write("        $chatWrap.html(\"\");\r\n");
      out.write("\r\n");
      out.write("        \r\n");
      out.write("        if(data.length > 0){\r\n");
      out.write("          \r\n");
      out.write("          // 읽지 않은 메세지 초기화\r\n");
      out.write("          countAll = 0;\r\n");
      out.write("          \r\n");
      out.write("          // 태그 동적 추가\r\n");
      out.write("          for(var i in data){\r\n");
      out.write("\r\n");
      out.write("            // ---------------- 공통코드 전역변수 영역 ----------------\r\n");
      out.write("            // 채팅 목록 영역 생성\r\n");
      out.write("            var $chattingArea = $(\"<li class='chattingArea'></li>\");\r\n");
      out.write("            // 프로필 영역 생성\r\n");
      out.write("            var $profileArea = $(\"<div class='profileArea'></div>\");\r\n");
      out.write("            // 미리보기 영역 생성\r\n");
      out.write("            var $previewArea = $(\"<div class='previewArea'></div>\");\r\n");
      out.write("            // 미리보기 제목 영역 생성\r\n");
      out.write("            var $previewTitleArea = $(\"<div class='previewTitleArea'></div>\");\r\n");
      out.write("            // 미리보기 설명 영역 생성\r\n");
      out.write("            var $previewDescription = $(\"<div class='previewDescription'></div>\");\r\n");
      out.write("          \r\n");
      out.write("\r\n");
      out.write("            // ---------------- 자신이 요청자 입장일 때 ----------------\r\n");
      out.write("            if(data[i].userNo == \"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${loginUser.userNo}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("\") {\r\n");
      out.write("\r\n");
      out.write("              // 채팅목록하나 생성\r\n");
      out.write("              var $chatting = $(\"<div class='chatting enterRoomList' onclick='enterRoom(this)'></div>\").attr(\"rno\",data[i].roomNo).attr(\"uno\",data[i].masterNo);\r\n");
      out.write("              \r\n");
      out.write("              // profileArea 에 profileImage 추가\r\n");
      out.write("              var $img = $(\"<img class='profileImage'>\").attr(\"src\", data[i].masterPic);\r\n");
      out.write("              $profileArea.append($img);\r\n");
      out.write("              \r\n");
      out.write("              // 현재 상대방이 로그인 상태 일 때\r\n");
      out.write("              if(loginList.indexOf(data[i].masterNo) != -1) {\r\n");
      out.write("                // online class속성 부여해서 온라인 체크등 표시\r\n");
      out.write("                $profileArea.append(\"<span class='online statusIndicator'></span>\");\r\n");
      out.write("              // 현재 상대방이 로그아웃 상태 일 때\r\n");
      out.write("              } else {\r\n");
      out.write("                // online class속성 제거해서 오프라인 체크등 표시\r\n");
      out.write("                $profileArea.append(\"<span class='statusIndicator'></span>\");\r\n");
      out.write("              }\r\n");
      out.write("\r\n");
      out.write("              // 상대방 닉네임 표시\r\n");
      out.write("              $previewTitleArea.append(\"<span class='previewNickname'>\" + data[i].masterNickname + \"</span>\");\r\n");
      out.write("\r\n");
      out.write("              // 상대방 프로펫시터 여부 표시\r\n");
      out.write("              if (data[i].masterPro == \"Y\") {\r\n");
      out.write("                $previewTitleArea.append(\"<span class='subText proPetsitter'>프로펫시터</span>\");\r\n");
      out.write("              } else if(data[i].masterPet == \"Y\") {\r\n");
      out.write("                $previewTitleArea.append(\"<span class='subText petsitter'>펫시터</span>\");\r\n");
      out.write("              }\r\n");
      out.write("              \r\n");
      out.write("              // 마지막 메세지 미리보기 표시\r\n");
      out.write("              $previewDescription.append(\"<span class='descriptionText'>나중에 메세지 표시부분 완료 후 기능추가예정</span>\");\r\n");
      out.write("              \r\n");
      out.write("              // 미리보기 제목 영역과 설명 영역을 미리보기 영역에 추가\r\n");
      out.write("              $previewArea.append($previewTitleArea);\r\n");
      out.write("              $previewArea.append($previewDescription);\r\n");
      out.write("\r\n");
      out.write("              // 프로필 영역과 미리보기 영역을 채팅목록하나에 추가\r\n");
      out.write("              $chatting.append($profileArea);\r\n");
      out.write("              $chatting.append($previewArea);\r\n");
      out.write("\r\n");
      out.write("              // 채팅목록하나를 chattingArea 에 추가\r\n");
      out.write("              $chattingArea.append($chatting);\r\n");
      out.write("\r\n");
      out.write("              // 채팅목록이 모두 생성된 후에 선택된 방의 정보와 일치하는 요소에 selected 클래스 추가\r\n");
      out.write("              if (selectedRoom && parseInt(selectedRoom.roomNo) === data[i].roomNo) {\r\n");
      out.write("                $chatting.addClass(\"selected\");\r\n");
      out.write("              }\r\n");
      out.write("\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // ---------------- 자신이 상대방 입장일 때 ----------------\r\n");
      out.write("            else {\r\n");
      out.write("\r\n");
      out.write("              // 채팅목록하나 생성\r\n");
